#!/usr/bin/env node
// Render a compact digest of a captured conversation log (JSONL on stdin).
import { createInterface } from 'node:readline';

const rl = createInterface({ input: process.stdin });
const out = [];
let t0 = null, tLast = null;
const toolCounts = new Map();
let lastAssistantTs = null;

function txt(c) {
  if (typeof c === 'string') return c;
  if (!Array.isArray(c)) return '';
  return c.filter(b => b.type === 'text').map(b => b.text).join('\n');
}

for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || null;
  if (ts) { if (!t0) t0 = ts; tLast = ts; }
  const short = ts ? ts.slice(11, 19) : '--------';

  if (e.type === 'queue-operation') {
    out.push(`\n[${short}] USER(queued): ${String(e.content).slice(0, 1200)}`);
    continue;
  }
  const m = e.message;
  if (!m) continue;
  if (e.type === 'user' || m.role === 'user') {
    const content = m.content;
    if (Array.isArray(content)) {
      const results = content.filter(b => b.type === 'tool_result');
      const t = txt(content);
      if (t.trim()) out.push(`\n[${short}] USER${e.isSidechain ? '(sub)' : ''}: ${t.slice(0, 1500)}`);
      for (const r of results) {
        let s = typeof r.content === 'string' ? r.content : (Array.isArray(r.content) ? r.content.filter(b=>b.type==='text').map(b=>b.text).join('\n') : '');
        if (r.is_error) out.push(`  [${short}] !! TOOL ERROR: ${String(s).slice(0, 500).replace(/\n/g, ' | ')}`);
      }
    } else if (typeof content === 'string' && content.trim()) {
      out.push(`\n[${short}] USER: ${content.slice(0, 1500)}`);
    }
  } else if (e.type === 'assistant' || m.role === 'assistant') {
    lastAssistantTs = ts;
    const content = m.content || [];
    const t = txt(content);
    if (t.trim()) out.push(`[${short}] AGENT${e.isSidechain ? '(sub)' : ''}: ${t.slice(0, 900)}`);
    for (const b of content) {
      if (b.type === 'tool_use') {
        toolCounts.set(b.name, (toolCounts.get(b.name) || 0) + 1);
        let arg = '';
        if (b.name === 'Bash') arg = String(b.input.command || '').slice(0, 260).replace(/\n/g, ' ; ');
        else if (b.input && (b.input.file_path || b.input.path)) arg = b.input.file_path || b.input.path;
        else if (b.input && b.input.pattern) arg = b.input.pattern;
        else if (b.input && b.input.prompt) arg = String(b.input.prompt).slice(0, 200);
        else arg = JSON.stringify(b.input || {}).slice(0, 200);
        out.push(`  [${short}] TOOL ${b.name}: ${arg}`);
      }
    }
  }
}

console.log(`=== span ${t0} -> ${tLast} ===`);
console.log(`=== tools: ${[...toolCounts.entries()].sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${k}:${v}`).join(' ')} ===`);
console.log(out.join('\n'));

